final class _FakePathProvider extends PathProviderPlatform {
  _FakePathProvider(this.appSupport);
  final Directory appSupport;
  @override
  Future<String?> getApplicationSupportPath() async => appSupport.path;
}

void main() {
  late Directory appSupport;
  setUp(() {
    appSupport = Directory.systemTemp.createTempSync('fah_pr2143_probe_');
    PathProviderPlatform.instance = _FakePathProvider(appSupport);
  });
  tearDown(() {
    if (appSupport.existsSync()) appSupport.deleteSync(recursive: true);
  });

  test('PR2143 probe: selector pick → save → restart → restore', () async {
    // Session 1: the user picks a folder through the selector ops
    // (the Windows/Linux production path).
    final env = await app_env.createDesktopEnv();
    final ops = defaultProjectFolderOps();
    expect(ops, isA<ProjectFolderSelectorOps>(), reason: 'VM test = linux');
    final picked = await ops!.pickDirectory();
    // Simulate the native dialog returning a host folder.
    final hostDir = Directory.systemTemp.createTempSync('fah_pr2143_host_');
    final applied = await pickAndApplyProjectMount(
      env: env,
      onApplied: () {},
      ops: _FixedPick(picked == null ? null : (path: hostDir.path, bookmark: picked.bookmark)),
    );
    expect(applied, hostDir.path, reason: 'in-session mount must work');
    final storedJson = File(
      '${appSupport.path}/project_mount.json',
    ).readAsStringSync();
    // ignore: avoid_print
    print('persisted record: $storedJson');

    // Session 2 (restart): mountedDesktopEnv must restore the mount.
    final env2 = await app_env.createDesktopEnv();
    final mount2 = env2 as ProjectMountEnv;
    // ignore: avoid_print
    print('after restart: mountedRoot=${mount2.mountedRoot} '
        'mountUnavailable=${mount2.mountUnavailable}');
    expect(
      mount2.mountedRoot,
      hostDir.path,
      reason: 'PR contract: mount persists across restarts',
    );
    hostDir.deleteSync(recursive: true);
  });
}

